```java
public CustomsReleaseResponse confirmRelease(String holdKey, CustomsReleaseRequest request) {
    ReleasePayload payload = new ReleasePayload(holdKey, request.operatorId());
    return idempotencyService.execute(request.requestId(), "CUSTOMS_RELEASE", 200, payload, CustomsReleaseResponse.class, () -> doConfirmRelease(holdKey, request));
}

private CustomsReleaseResponse doConfirmRelease(String holdKey, CustomsReleaseRequest request) {
    HoldRow hold = lockHold(holdKey);
    if (hold == null) throw notFound("暂扣记录不存在: " + holdKey);
    if (HOLD_RELEASED.equals(hold.status())) throw conflict("暂扣已解除，不得重复确认");
    Instant now = clock.get();
    if (hold.firstOperator() == null) {
        jdbcTemplate.update("UPDATE customs_hold SET first_operator=?, first_confirmed_at=? WHERE hold_key=?", operator, now, holdKey);
        return new CustomsReleaseResponse(holdKey, hold.bagTag(), "PENDING_SECOND_CONFIRM", operator, now.toString(), null, null, BAG_CUSTOMS_HOLD);
    }
    if (hold.firstOperator().equals(request.operatorId())) throw unprocessable("同一操作人不得重复确认");
    // second confirm: atomically release
    BagRow bag = lockBag(hold.bagTag());
    jdbcTemplate.update("UPDATE customs_hold SET second_operator=?, second_confirmed_at=?, status=? WHERE hold_key=?", ...);
    jdbcTemplate.update("UPDATE bag SET status=? WHERE bag_tag=?", hold.previousStatus(), hold.bagTag());
    insertEvent(hold.bagTag(), EVT_CUSTOMS_RELEASED, null, bag.currentLocation());
    return new CustomsReleaseResponse(holdKey, hold.bagTag(), "RELEASED", hold.firstOperator(), hold.firstConfirmedAt().toString(), operator, now.toString(), hold.previousStatus());
}
